    {
      "before": "    if version == \"v1\":\n        fields[\"name\"] = entity.name\n",
      "after": "    if version == \"v1\":\n        fields[\"display_name\"] = entity.display_name\n"
    },
    {
      "before": "        entity = module.Entity(entity_id=\"py_101\")\n        if args.version == \"v1\":\n            entity.name = \"Sensor A\"\n",
      "after": "        entity = module.Entity(entity_id=\"py_101\")\n        if args.version == \"v1\":\n            entity.display_name = \"Sensor A\"\n"
    }
  ],
  "rationale": "Two edits update the Python runtime to use the regenerated v1 accessor 'display_name' (wire field 2) and the observation key 'display_name'. v2 is unchanged. The subscribe path reuses process_entity so both schema-version topics are handled.",
  "confidence": 0.99,
  "assumptions": [
    "Regenerated Python bindings expose the field as 'display_name'.",
    "No other source files need changes for this runtime.",
    "The in-memory pub/sub delivers base64-encoded protobuf bytes for both entity.v1 and entity.v2 topics."
  ]
}
